const raw = $input.first().binary.data.data;
const d = JSON.parse(Buffer.from(raw, 'base64').toString('utf8'));
return [{
  json: d,
  binary: $('Switch').first().binary
}];

const item = $input.first();
const profile = $('Leggi Profile Objectives').first().json;
const soglie = $('Parsa Objectives').first().json;
const cuatrimestre = soglie.cuatrimestre.replace(/ /g, '_');
const chiave = 'soglie_' + cuatrimestre;

profile[chiave] = {
  soglie_ka: soglie.soglie_ka,
  premio_per_soglia_ka: soglie.premio_per_soglia_ka,
  soglie_filiale: soglie.soglie_filiale,
  premio_per_soglia_filiale: soglie.premio_per_soglia_filiale
};

const jsonStr = JSON.stringify(profile, null, 2);

item.json = { collaboratore: profile.collaboratore };
item.binary = {
  data: {
    data: Buffer.from(jsonStr).toString('base64'),
    mimeType: 'application/json',
    fileName: `profile_${profile.collaboratore}.json`
  }
};

return [item];

const rawText = $input.first().json.content[0].text;
const jsonStr = rawText.replace(/```json\n?|\n?```/g, '').trim();
const d = JSON.parse(jsonStr);

return [{
  json: {
    collaboratore: d.collaboratore,
    cuatrimestre: d.cuatrimestre
      .replace('1er', 'Primer')
      .replace('2do', 'Segundo')
      .replace('3er', 'Tercer'),
    soglie_ka: d.soglie_ka,
    premio_per_soglia_ka: d.premio_per_soglia_ka,
    soglie_filiale: d.soglie_filiale,
    premio_per_soglia_filiale: d.premio_per_soglia_filiale
  },
  binary: $input.first().binary
}];

const data = $json;
const nomeFile = data.tipo === 'filiale'
  ? `qlik_${data.paese}_filiale_${data.cuatrimestre.replace(/ /g, '_')}.json`
  : `qlik_${data.collaboratore}_${data.cuatrimestre.replace(/ /g, '_')}.json`;
const bufferData = data.tipo === 'filiale'
  ? {
      paese: data.paese,
      cuatrimestre: data.cuatrimestre,
      anno: new Date().getFullYear(),
      mesi: data.mesi,
      tipo: data.tipo,
      valore_totale_filiale: data.valore_totale_filiale,
      imagenFileId: data.fileId
    }
  : {
      collaboratore: data.collaboratore,
      paese: data.paese,
      cuatrimestre: data.cuatrimestre,
      anno: new Date().getFullYear(),
      invoiced: data.invoiced,
      mesi: data.mesi,
      tipo: data.tipo,
      imagenFileId: data.fileId,
      countryMismatch: data.countryMismatch ?? false,
      paeseQlik: data.paeseQlik ?? null,
      paeseSupabase: data.paeseSupabase ?? null,
      collaboratorTypeName: data.collaboratorTypeName ?? null
    };
return {
  json: {
    ...data,
    nomeFile,
    bufferData: JSON.stringify(bufferData, null, 2)
  }
};

const collaboratoriRaw = $('Verifica Collaboratore Supabase').all().map(item => item.json);
const collaboratoriMap = new Map();
collaboratoriRaw.forEach(c => collaboratoriMap.set(c.CollaboratorId, c));
const collaboratori = Array.from(collaboratoriMap.values());
const normalizza = (s) => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, '')
  .toLowerCase();
const items = $('Estrai Dati Qlik').all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const data = items[i].json;
  if (data.tipo !== 'individuale') {
    results.push({ json: { ...data, collaboratorMatchStatus: 'skip' }, pairedItem: i });
    continue;
  }
  const nomeQlik = normalizza(data.collaboratore);
  const match = collaboratori.find(c => normalizza(c.CollaboratorName) === nomeQlik);
  if (!match) {
    results.push({ json: { ...data, collaboratorMatchStatus: 'not_found' }, pairedItem: i });
  } else {
    const paeseSupabase = match.Country?.CountryName || null;
    const paeseQlik = data.paese || null;
    const countryMismatch = paeseSupabase && paeseQlik
      ? normalizza(paeseSupabase) !== normalizza(paeseQlik)
      : false;
    const collaboratorTypeName = match.CollaboratorType?.CollaboratorTypeName || null;
    results.push({
      json: {
        ...data,
        collaboratorId: match.CollaboratorId,
        collaboratorMatchStatus: 'found',
        countryMismatch,
        paeseQlik,
        paeseSupabase,
        collaboratorTypeName
      },
      pairedItem: i
    });
  }
}
return results;

const rawText = $('Analyze image').item.json.content[0].text;
const jsonStr = rawText.replace(/```json\n?|\n?```/g, '').trim();
const data = JSON.parse(jsonStr);

const mesiMap = {
  'jan,feb,mar,apr': '1er Cuatrimestre',
  'may,jun,jul,ago': '2do Cuatrimestre',
  'sep,oct,nov,dic': '3er Cuatrimestre'
};
const mesiQ1 = ['jan', 'feb', 'mar', 'apr'];
const mesiQ2 = ['may', 'jun', 'jul', 'ago'];
const anno = new Date().getFullYear();
const mesiKey = data.mesi_selezionati.join(',');
const primoMese = data.mesi_selezionati[0];

let cuatrimestre;
if (mesiMap[mesiKey]) {
  cuatrimestre = mesiMap[mesiKey] + ' ' + anno;
} else if (mesiQ1.includes(primoMese)) {
  cuatrimestre = '1er Cuatrimestre ' + anno;
} else if (mesiQ2.includes(primoMese)) {
  cuatrimestre = '2do Cuatrimestre ' + anno;
} else {
  cuatrimestre = '3er Cuatrimestre ' + anno;
}

if (data.tipo === 'individuale') {
  const invoiced = parseFloat(String(data.valore_totale_invoiced).replace(/\./g, '').replace(',', '.'));
  return { json: {
    tipo: 'individuale',
    collaboratore: data.collaboratore,
    paese: data.paese,
    mesi: data.mesi_selezionati,
    cuatrimestre,
    invoiced,
    fileId: $('Classifica File').item.json.fileId
  }};
}

if (data.tipo === 'filiale') {
  return { json: {
    tipo: 'filiale',
    paese: data.paese,
    mesi: data.mesi_selezionati,
    cuatrimestre,
    valore_totale_filiale: data.valore_totale_filiale,
    fileId: $('Classifica File').item.json.fileId
  }};
}

throw new Error('Tipo immagine non riconosciuto: ' + data.tipo);

const mimeType = $('Google Drive Trigger').item.json.mimeType;
const fileId = $('Google Drive Trigger').item.json.id;
const fileName = $('Google Drive Trigger').item.json.name;

let fileType;
if (mimeType === 'application/pdf') fileType = 'objectives';
else if (mimeType.startsWith('image/')) fileType = 'results';
else if (mimeType === 'message/rfc822' || fileName.endsWith('.eml')) fileType = 'email';
else fileType = 'unknown';

return { 
  json: { fileId, fileName, mimeType, fileType },
  binary: $('Download file').item.binary
};

const prepara = $('Prepara Buffer Qlik').all();

return prepara.map((p, i) => {
  const found = $input.all().find(item => item.json && item.json.id && item.json.name === p.json.nomeFile);

  return {
    json: {
      ...p.json,
      bufferFileId: found ? found.json.id : null
    },
    pairedItem: i
  };
});
